function colorsFor(slug: string, model: string, definitions: ColorDefinition[]) {
  return definitions.map(([code, name, fileSlug]) => ({
    code,
    name,
    image: mediaUrl(`/images/products/dental-chair/${slug}/colors/${slug}-${fileSlug}.avif`),
    swatch: mediaUrl(`/images/products/dental-chair/${slug}/colors/swatches/${slug}-${fileSlug}-swatch.avif`),
    alt: `${model} dental chair shown with ${code} ${name} full-silicone upholstery`,
    description: `${code} ${name} full-silicone upholstery for coordinated treatment-room interiors.`,
  }));
}

